import ghidra.app.script.GhidraScript;
import ghidra.app.decompiler.*;
import java.nio.file.*;
public class BoardCoreInteractive extends GhidraScript{
 public void run()throws Exception{Path out=Paths.get(getScriptArgs()[0]);Files.createDirectories(out);Path queue=out.resolve("jobs.txt");if(!Files.exists(queue))Files.writeString(queue,"");var cookie=getFunctionAt(toAddr("181571b80"));if(cookie!=null)cookie.setNoReturn(false);var dec=new DecompInterface();dec.openProgram(currentProgram);int done=0;long until=System.currentTimeMillis()+600000;Files.writeString(out.resolve("ready.txt"),"ready");while(System.currentTimeMillis()<until&&!monitor.isCancelled()){var jobs=Files.readAllLines(queue);if(done>=jobs.size()){Thread.sleep(200);continue;}String line=jobs.get(done++).trim();if(line.equals("stop"))break;if(line.isEmpty())continue;try{String[] args=line.split(" +");var address=toAddr(args[0]);if(args.length>1&&args[1].equals("refs")){var refs=new StringBuilder();for(var ref:getReferencesTo(address)){var from=ref.getFromAddress();var caller=getFunctionContaining(from);refs.append(from).append("\t").append(caller==null?"?":caller.getEntryPoint()).append("\t").append(ref.getReferenceType()).append("\n");}Files.writeString(out.resolve(args[0]+"-refs.tsv"),refs.toString());}else if(args.length>1&&args[1].equals("asm")){var function=getFunctionAt(address);var listing=new StringBuilder();if(function!=null){var instructions=currentProgram.getListing().getInstructions(function.getBody(),true);while(instructions.hasNext()){var instruction=instructions.next();listing.append(instruction.getAddress()).append(" ").append(instruction).append("\n");}}Files.writeString(out.resolve(args[0]+".asm"),listing.toString());}else if(args.length>1){int size=Math.min(Integer.parseInt(args[1]),4096);byte[] bytes=new byte[size];currentProgram.getMemory().getBytes(address,bytes);Files.write(out.resolve(args[0]+".bin"),bytes);}else{var f=getFunctionAt(address);if(f==null){disassemble(address);f=createFunction(address,null);}if(f!=null){f.setNoReturn(false);var result=dec.decompileFunction(f,45,monitor);if(result.decompileCompleted())Files.writeString(out.resolve(f.getEntryPoint()+".c"),result.getDecompiledFunction().getC());var graph=new StringBuilder();for(var target:f.getCalledFunctions(monitor))graph.append(target.getEntryPoint()).append("\t").append(target.getName(true)).append("\n");Files.writeString(out.resolve(f.getEntryPoint()+"-calls.tsv"),graph.toString());}}Files.writeString(out.resolve("completed.txt"),done+" "+line);}catch(Exception e){Files.writeString(out.resolve("error-"+done+".txt"),e.toString());}}dec.dispose();Files.writeString(out.resolve("stopped.txt"),"stopped");}
}
